!solve(input){ 
    let { stack, action, value, history } = input;
    if (action === "push") {
        history.push({ stack: [...stack], action: "push", value });
        stack = [...stack, value];
    } else if (action === "pop") {
        if (stack.length > 0) {
            history.push({ stack: [...stack], action: "pop" });
            stack = stack.slice(0, -1);
        }
    } else if (action === "rollback") {
        if (history.length > 0) {
            let lastAction = history.pop();
            stack = lastAction.stack;
        }
    }
    return { stack, history };
}

