!solve(input){
    var tokens = [];
    var i = 0;
    while(i < input.length){
        if(input[i] == '+' || input[i] == '-' || input[i] == '*' || input[i] == '/'){
            tokens.push(["OP", input[i]]);
            i++;
        } else if(isNaN(input[i])){
            var j = i;
            while(j < input.length && isNaN(input[j])){
                j++;
            }
            tokens.push(["ID", input.substring(i, j)]);
            i = j;
        } else {
            var j = i;
            while(j < input.length && !isNaN(input[j])){
                j++;
            }
            tokens.push(["NUM", input.substring(i, j)]);
            i = j;
        }
    }
    return tokens;
}
